+    assert_eq!(got, ["app ops (1 fn) | test -j 6 -p camcraft-app --test ops -- --test-threads=6 --exact op_area"]);
+    let heavy: Vec<String> = steps(quick_plan(&fx.0, &[f], &[], &hunks, true)).iter().map(line).collect();
